@startuml

class Course {
  + name : string
}

class Edition {
  + participantsCount : int
}

class Lesson {
  + date : date
  + startTime : time
  + duration : int
}

class Resource {
  + name : string
}

class Teacher {
  + name : string
}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

class MasterStudent {}

class ExternalAuditor {}

class LessonResource {
}

Course "1" *-- "1..*" Edition
Edition "1" *-- "1..*" Lesson
Edition "1" -- "1" InternalTeacher : responsible
Edition "1" -- "*" MasterStudent : enrolled
Edition "1" -- "*" ExternalAuditor : enrolled
Lesson "*" -- "*" Teacher : taught_by
Teacher "0..*" -- "0..*" Course : assigned_to
Lesson "1" -- "1" Resource : requires
Lesson "1" -- "1" LessonResource
LessonResource "*" -- "1" Resource

@enduml

